-- ============================================================
-- Datos de prueba: 1 torneo, 48 equipos (12 grupos de 4), 816 jugadores,
-- 48 entrenadores, 40 arbitros, 20 canchas y 72 partidos programados.
-- Usuarios de prueba (clave de todos: Prueba12345):
--   admin@canchasrola.test (ADMIN), organizador@canchasrola.test (ORGANIZADOR),
--   espectador1..3@canchasrola.test (ESPECTADOR)
-- ATENCION: este script VACIA todas las tablas antes de insertar.
-- ============================================================
USE futbol_bogota;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

TRUNCATE TABLE alineacion;
TRUNCATE TABLE arbitro;
TRUNCATE TABLE auditoria;
TRUNCATE TABLE cancha;
TRUNCATE TABLE correo_arbitro;
TRUNCATE TABLE correo_entrenador;
TRUNCATE TABLE correo_jugador;
TRUNCATE TABLE entrenador;
TRUNCATE TABLE equ_gru;
TRUNCATE TABLE equ_tor;
TRUNCATE TABLE equipo;
TRUNCATE TABLE evento_partido;
TRUNCATE TABLE grupo;
TRUNCATE TABLE inscripcion_jugador;
TRUNCATE TABLE jugador;
TRUNCATE TABLE par_arb;
TRUNCATE TABLE par_equ;
TRUNCATE TABLE partido;
TRUNCATE TABLE telefono_arbitro;
TRUNCATE TABLE telefono_entrenador;
TRUNCATE TABLE telefono_jugador;
TRUNCATE TABLE tor_usu;
TRUNCATE TABLE torneo;
TRUNCATE TABLE usuario;






















SET FOREIGN_KEY_CHECKS = 1;

SELECT 'Listo' AS resultado, (SELECT COUNT(*) FROM equipo) AS equipos, (SELECT COUNT(*) FROM jugador) AS jugadores, (SELECT COUNT(*) FROM entrenador) AS entrenadores, (SELECT COUNT(*) FROM partido) AS partidos;
